create extension if not exists pgcrypto;
create type candidate_status as enum ('candidate','researching','sample','approved','rejected');
create type sku_status as enum ('testing','watching','potential','core','eliminate','archived');
create table profiles (id uuid primary key references auth.users(id) on delete cascade, display_name text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table candidate_products (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, name text not null, category text not null, description text, estimated_cost numeric(12,2), estimated_price numeric(12,2), weight numeric(12,2), length numeric(12,2), width numeric(12,2), height numeric(12,2), material text, fragile boolean not null default false, electronic boolean not null default false, requires_installation boolean not null default false, after_sale_risk smallint check(after_sale_risk between 0 and 100), competition_level smallint check(competition_level between 0 and 100), visual_potential smallint check(visual_potential between 0 and 100), bundle_potential smallint check(bundle_potential between 0 and 100), ai_operation_fit smallint check(ai_operation_fit between 0 and 100), gross_margin_score smallint check(gross_margin_score between 0 and 100), logistics_score smallint check(logistics_score between 0 and 100), after_sale_score smallint check(after_sale_score between 0 and 100), visual_score smallint check(visual_score between 0 and 100), differentiation_score smallint check(differentiation_score between 0 and 100), ai_fit_score smallint check(ai_fit_score between 0 and 100), testing_cost_score smallint check(testing_cost_score between 0 and 100), total_score numeric(5,2), status candidate_status not null default 'candidate', notes text, is_demo boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table suppliers (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, name text not null, platform text, contact_name text, contact_info text, url text, location text, rating numeric(3,2), notes text, is_demo boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table supplier_products (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, supplier_id uuid not null references suppliers(id) on delete cascade, candidate_product_id uuid not null references candidate_products(id) on delete cascade, supplier_sku text, purchase_price numeric(12,2), minimum_order_quantity integer, supports_dropshipping boolean default false, shipping_time_hours integer, return_policy text, weight numeric(12,2), length numeric(12,2), width numeric(12,2), height numeric(12,2), sample_price numeric(12,2), url text, notes text, unique(supplier_id,candidate_product_id));
create table skus (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, sku_code text not null, name text not null, short_name text, candidate_product_id uuid references candidate_products(id), primary_supplier_id uuid references suppliers(id), category text not null, cost numeric(12,2) not null default 0, sale_price numeric(12,2) not null default 0, weight numeric(12,2), stock integer not null default 0, status sku_status not null default 'testing', launch_date date, description text, material text, size_description text, package_description text, installation_description text, shipping_description text, return_description text, warnings text, is_demo boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(user_id,sku_code));
create table sku_daily_metrics (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, sku_id uuid not null references skus(id) on delete cascade, date date not null, impressions integer not null default 0 check(impressions>=0), clicks integer not null default 0 check(clicks>=0), visitors integer not null default 0 check(visitors>=0), favorites integer not null default 0, add_to_cart integer not null default 0, orders integer not null default 0, units_sold integer not null default 0, revenue numeric(12,2) not null default 0, refund_orders integer not null default 0, refund_amount numeric(12,2) not null default 0, ad_spend numeric(12,2) not null default 0, platform_fees numeric(12,2) not null default 0, is_demo boolean not null default false, created_at timestamptz not null default now(), unique(sku_id,date));
create index metrics_user_date_idx on sku_daily_metrics(user_id,date desc); create index skus_user_status_idx on skus(user_id,status);
alter table profiles enable row level security; alter table candidate_products enable row level security; alter table suppliers enable row level security; alter table supplier_products enable row level security; alter table skus enable row level security; alter table sku_daily_metrics enable row level security;
create policy "own profile" on profiles for all using(id=auth.uid()) with check(id=auth.uid());
create policy "own candidates" on candidate_products for all using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy "own suppliers" on suppliers for all using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy "own supplier products" on supplier_products for all using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy "own skus" on skus for all using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy "own metrics" on sku_daily_metrics for all using(user_id=auth.uid()) with check(user_id=auth.uid());
